 if(/^Flip a coin\. If tails, this attack does nothing\. If heads, during your opponent's next turn, prevent all damage from(?:—and | and )effects of(?:—| )attacks done to this Pokémon\.$/.test(text))return ok({type:'coinAttackGate',heads:{type:'preventDamage',target:'self',duration:'opponentTurn',effects:true}});
 if((m=text.match(/^Flip (\d+) coins\. This attack does (\d+) damage for each heads\. This Pokémon is now Confused\.$/)))return ok(sequence([{type:'coinDamage',coins:+m[1],amount:+m[2],mode:'replace'},{type:'status',target:'self',status:'confusion'}]));
 if((m=text.match(/^Switch this Pokémon with 1 of your Benched \{([GRWLPFDMC])\} Pokémon\.$/)))return ok({type:'switch',side:'self',filter:{subtype:energyName(m[1])}});
 if(/^Halve your opponent's Active Pokémon's remaining HP, rounded down\.$/.test(text))return ok({type:'halveRemainingHp',target:'opponentActive'});
 if((m=text.match(/^Flip a coin\. If heads, your opponent's Active Pokémon's remaining HP is now (\d+)\.$/)))return ok({type:'coinFlip',heads:{type:'setRemainingHp',target:'opponentActive',amount:+m[1]}});
 if((m=text.match(/^Heal (\d+) damage and remove a random Special Condition from your Active Pokémon\.$/)))return ok(sequence([{type:'heal',target:'selfActive',amount:+m[1]},{type:'removeRandomStatus',target:'selfActive'}]));
 if((m=text.match(/^Take (\d+) \{([GRWLPFDMC])\} Energy from your Energy Zone and attach it to this Pokémon\. If you do, do (\d+) damage to this Pokémon\.$/)))return ok(sequence([{type:'attachEnergy',target:'self',energyType:energyName(m[2]),amount:+m[1]},{type:'selfDamage',amount:+m[3]}]));
 if((m=text.match(/^Discard (\d+) \{([GRWLPFDMC])\} Energy from this Pokémon, and this attack does (\d+) damage to each of your opponent's Pokémon\.$/)))return ok(sequence([{type:'discardEnergy',target:'self',energyType:energyName(m[2]),amount:+m[1]},{type:'damage',target:'opponentAll',amount:+m[3]}]));
 if((m=text.match(/^This attack does (\d+) damage to each of your opponent's Pokémon\.$/)))return ok(sequence([{type:'damage',target:'opponentActive',amount:+m[1]},{type:'benchDamage',side:'opponent',amount:+m[1],all:true}]));
 if((m=text.match(/^Put (\d+) random Basic Pokémon from your deck onto your Bench\.$/)))return ok({type:'benchFromDeck',amount:+m[1],filter:{kind:'pokemon',stage:'Basic'}});
 if((m=text.match(/^Put (\d+) random ([A-Z][A-Za-zé♀♂:' -]+) from your deck onto your Bench\.$/)))return ok({type:'benchFromDeck',amount:+m[1],filter:{kind:'pokemon',name:m[2]}});
 if(/^Discard a random card from your opponent's hand\.$/.test(text))return ok({type:'discardHand',side:'opponent',amount:1,random:true});
