 if(/^During your opponent's next turn, if the Defending Pokémon tries to use an attack, your opponent flips a coin\. If tails, that attack doesn't happen\.$/.test(text))return ok({type:'attackCoinGate',target:'opponentActive',duration:'opponentTurn'});
 if((m=text.match(/^During your opponent's next turn, if this Pokémon is damaged by an attack, do (\d+) damage to the Attacking Pokémon\.$/)))return ok({type:'retaliateDamage',target:'self',amount:+m[1],duration:'opponentTurn'});
 if((m=text.match(/^If this Pokémon has any \{([GRWLPFDMC])\} Energy attached, this attack does (\d+) more damage\.$/)))return ok({type:'bonusDamage',amount:+m[2],condition:{type:'selfHasEnergyType',energyType:energyName(m[1])}});
