 if((m=text.match(/^If your opponent's Active Pokémon is ([A-Z][A-Za-zé♀♂:' -]+), this attack does (\d+) more damage\.$/))&&!statusNames[m[1]])return ok({type:'bonusDamage',amount:+m[2],condition:{type:'opponentMatches',filter:{name:m[1]}}});
