 if((m=text.match(/^If this Pokémon and your opponent's Active Pokémon have the same amount of Energy attached, this attack does (\d+) more damage\.$/)))return ok({type:'bonusDamage',amount:+m[1],condition:{type:'equalEnergyCount'}});
 if((m=text.match(/^If you have the same number of cards in your hand as your opponent, this attack does (\d+) more damage\.$/)))return ok({type:'bonusDamage',amount:+m[1],condition:{type:'handSizesEqual'}});
