 if((m=text.match(/^If your opponent has exactly ([0-9, or]+) cards in their hand, this attack does (\d+) more damage\.$/))){const values=(m[1].match(/\d+/g)||[]).map(Number);return ok({type:'bonusDamage',amount:+m[2],condition:{type:'opponentHandSizeOneOf',values}});}
 if((m=text.match(/^If this Pokémon has (\d+) or more different types of Energy attached, this attack does (\d+) more damage\.$/)))return ok({type:'bonusDamage',amount:+m[2],condition:{type:'selfDistinctEnergyTypesAtLeast',amount:+m[1]}});
 if((m=text.match(/^If this Pokémon evolved from .+ during this turn, this attack does (\d+) more damage\.$/)))return ok({type:'bonusDamage',amount:+m[1],condition:{type:'evolvedThisTurn'}});
 if((m=text.match(/^If your opponent has gotten exactly (\d+) points?, this attack does (\d+) more damage\.$/)))return ok({type:'bonusDamage',amount:+m[2],condition:{type:'opponentPointsExact',amount:+m[1]}});
 if((m=text.match(/^If the amount of Energy attached to both Active Pokémon is (\d+) or more, this attack does (\d+) more damage\.$/)))return ok({type:'bonusDamage',amount:+m[2],condition:{type:'combinedActiveEnergyAtLeast',amount:+m[1]}});
 if((m=text.match(/^If you have (\d+) or more \{([GRWLPFDMC])\} Energy in play, this attack does (\d+) more damage\.$/)))return ok({type:'bonusDamage',amount:+m[3],condition:{type:'teamEnergyAtLeast',amount:+m[1],energyType:energyName(m[2])}});
 if((m=text.match(/^If your Pokémon in play have (\d+) or more different types of Energy attached, this attack does (\d+) more damage\.$/)))return ok({type:'bonusDamage',amount:+m[2],condition:{type:'teamDistinctEnergyTypesAtLeast',amount:+m[1]}});
 if((m=text.match(/^If your opponent has any \{([GRWLPFDMC])\} Pokémon in play, this attack does (\d+) more damage\.$/)))return ok({type:'bonusDamage',amount:+m[2],condition:{type:'pokemonPresent',side:'opponent',zone:'inPlay',filter:{subtype:energyName(m[1])}}});
